SET FOREIGN_KEY_CHECKS=0;
SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";

-- Migrations Table
CREATE TABLE IF NOT EXISTS `migrations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `migration` varchar(191) NOT NULL,
  `batch` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `users` (`id` int unsigned not null auto_increment primary key, `name` varchar(255) not null, `password` varchar(255) not null, `remember_token` varchar(100) null, `phone` varchar(20) not null, `email` varchar(255) null, `shipping_area` varchar(100) null, `shipping_address` text null, `role` enum('admin', 'manager', 'user') not null default 'user', `custom_role` varchar(50) null, `permissions_json` text null, `status` enum('active', 'inactive') not null default 'active', `last_login_at` timestamp null, `reset_token_hash` varchar(255) null, `reset_token_expires_at` timestamp null, `created_at` timestamp not null default CURRENT_TIMESTAMP);
