t null default '0', `is_archived` tinyint(1) not null default '0', `meta` json null, `stock` int not null default '0', `low_stock_alert` int not null default '10', `min_order` int not null default '1', `max_order` int null, `unlimited_stock` tinyint(1) not null default '0', `backorder` tinyint(1) not null default '0', `track_inventory` tinyint(1) not null default '1', `stock_status` varchar(20) not null default 'in_stock', `product_status` varchar(30) not null default 'published', `images` json null, `size_options` json null, `color_options` json null, `payment_methods` json null, `payment_phone_number` varchar(20) null, `status` enum('active', 'inactive') not null default 'active', `created_at` timestamp not null default CURRENT_TIMESTAMP);
